N=22
out=[[5]*N for _ in range(N)]
def add_frame(r,c,border,core):
    for dr in range(5):
        for dc in range(5):
            out[r+dr][c+dc]=core if 1<=dr<=3 and 1<=dc<=3 else border
for r,c,b,core in [(3,0,8,9),(5,17,2,4),(9,12,2,3),(12,5,8,1),(16,0,8,2),(16,17,2,9)]:
    add_frame(r,c,b,core)
print('\n'.join(' '.join(map(str,row)) for row in out))
